<x-capstone::dialog id="add-member" title="Add Member" description="Enter the email address of the student you want to invite to your group."><form class="space-y-4 mt-4" @submit.prevent="addMember()"><label class="grid gap-2 text-sm font-medium">Email<x-capstone::input type="email" x-model="memberEmail" required placeholder="student@example.com" /></label><p class="text-sm text-destructive" role="alert" x-text="errors.root"></p><div class="flex justify-end gap-2"><x-capstone::button variant="outline" @click="close('add-member')">Cancel</x-capstone::button><x-capstone::button type="submit" ::disabled="saving">Add Member</x-capstone::button></div></form></x-capstone::dialog>
<x-capstone::dialog id="group-confirm"><h2 class="text-lg font-semibold pr-6" x-text="confirmTitle"></h2><p class="text-sm text-muted-foreground mt-2" x-text="confirmMessage"></p><p class="text-sm text-destructive mt-3" role="alert" x-text="errors.root"></p><div class="mt-6 flex justify-end gap-2"><x-capstone::button variant="outline" @click="close('group-confirm')">Cancel</x-capstone::button><x-capstone::button @click="confirmSave()" ::disabled="saving">Confirm</x-capstone::button></div></x-capstone::dialog>
